(() => {
 const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,loader=$('#loader');let intro,failSafe;
 function finishIntro(){clearTimeout(failSafe);intro?.kill();if(!loader)return;loader.classList.remove('active');loader.setAttribute('aria-hidden','true');document.body.classList.remove('loading');if(loader.contains(document.activeElement))$('.brand').focus();}
 function runIntro(){if(!loader||reduce||!window.gsap){finishIntro();return;}loader.classList.add('active');loader.removeAttribute('aria-hidden');document.body.classList.add('loading');gsap.set(loader,{clipPath:'inset(0% 0% 0% 0%)'});gsap.set('.piece',{opacity:0});gsap.set('.logo-build',{opacity:1,y:0});gsap.set('.loader-drawing',{opacity:.2});gsap.set('.loader-drawing path',{strokeDashoffset:2400});gsap.set('.load-rule>span',{width:'0%'});intro=gsap.timeline({onComplete:finishIntro});intro.to('.loader-drawing path',{strokeDashoffset:0,duration:1.5,ease:'power2.inOut'},0).fromTo('.piece-1',{y:28,opacity:0},{y:0,opacity:1,duration:.6,ease:'expo.out'},.25).fromTo('.piece-2',{y:-28,opacity:0},{y:0,opacity:1,duration:.6,ease:'expo.out'},.5).fromTo('.piece-3',{x:-35,opacity:0},{x:0,opacity:1,duration:.6,ease:'expo.out'},.8).fromTo('.piece-4',{x:35,opacity:0},{x:0,opacity:1,duration:.6,ease:'expo.out'},1).fromTo('.piece-5',{y:18,opacity:0},{y:0,opacity:1,duration:.6,ease:'expo.out'},1.3).fromTo('.piece-6',{y:12,opacity:0},{y:0,opacity:1,duration:.5,ease:'expo.out'},1.6).to('.load-rule>span',{width:'100%',duration:2.1,ease:'power2.inOut'},0).to('.loader-drawing',{opacity:0,duration:.4},1.8).to('.logo-build',{opacity:0,y:-12,duration:.4},2.35).to(loader,{clipPath:'inset(0% 0% 100% 0%)',duration:.8,ease:'expo.inOut'},2.6);failSafe=setTimeout(finishIntro,6000);}
 $('#skip-intro')?.addEventListener('click',finishIntro);$('#replay-intro')?.addEventListener('click',()=>{window.scrollTo({top:0,behavior:'instant'});runIntro();});document.addEventListener('keydown',e=>{if(e.key==='Escape')finishIntro();});let seen=false;try{seen=sessionStorage.getItem('hn-intro-seen')==='1';sessionStorage.setItem('hn-intro-seen','1');}catch{}if(loader&&!seen)runIntro();else finishIntro();
 const cursor=$('#cursor');if(cursor&&matchMedia('(hover:hover) and (pointer:fine)').matches&&!reduce){document.addEventListener('pointermove',e=>{document.body.classList.add('cursor-ready');cursor.style.transform=`translate(${e.clientX-15}px,${e.clientY-15}px)`;},{passive:true});document.addEventListener('pointerover',e=>{cursor.classList.toggle('hover',!!e.target.closest('a,button,summary,input,textarea,select'));});document.addEventListener('pointerleave',()=>document.body.classList.remove('cursor-ready'));}
 if(window.gsap&&!reduce){$$('[data-liquid]').forEach(tile=>{const d=$(`#liquid-${tile.dataset.liquid} feDisplacementMap`);function reveal(){if(!d)return;gsap.killTweensOf(d);gsap.fromTo(d,{attr:{scale:36}},{attr:{scale:0},duration:.85,ease:'power3.out'});}tile.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')reveal();});tile.addEventListener('focus',reveal);});}
 const menu=$('#site-menu'),toggle=$('.menu-toggle');
 if(menu&&toggle){toggle.addEventListener('click',()=>{menu.showModal();document.body.classList.add('menu-open');});function closeMenu(){menu.close();document.body.classList.remove('menu-open');}$('.menu-close').addEventListener('click',closeMenu);menu.addEventListener('close',()=>document.body.classList.remove('menu-open'));menu.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',closeMenu));}
 $$('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
})();
